int multiply(int x, int y) { return x * y; }

using namespace std::placeholders;

// Fix first argument to 5
auto f1 = std::bind(multiply, 5, _1);
int result1 = f1(3); // 15

// Reorder arguments
auto f2 = std::bind(multiply, _2, _1);
int result2 = f2(10, 2); // 2 * 10 = 20
