// Custom Binder (Partial Application)
template <typename F, typename Arg1>
struct CustomPartial {
    F f; Arg1 a1;
    CustomPartial(F fun, Arg1 v1) : f(fun), a1(v1) {}

    int operator()(int runtime_arg) {
        return f(a1, runtime_arg);
    }
};

int sub(int x, int y) { return x - y; }

auto subtract_from_100 = CustomPartial(sub, 100);

int res = subtract_from_100(10); // 90
